func (this *Coinbaseinternational) ParseMarket(market any) map[string]any {
	var instrumentName *string = this.SafeString(market, "instrument_name")
	var lowercaseId *string = this.SafeStringLower(market, "instrument_name")
	var baseId *string = this.SafeString(market, "base_currency")
	var quoteId *string = this.SafeString(market, "counter_currency")
	var settleId *string = this.SafeString(market, "settlement_currency", quoteId)
	var kind *string = this.SafeString(market, "kind", "")
	var settlementPeriod *string = this.SafeString(market, "settlement_period")
	var isSpot bool = (kind != nil && *kind == "spot")
	var isPerpetual bool = (settlementPeriod != nil && *settlementPeriod == "perpetual")
	var isFuture bool = !isPerpetual && (strings.Index(*kind, "future") >= 0)
	var isOption bool = (strings.Index(*kind, "option") >= 0)
	var comboPosition int = strings.Index(*kind, "combo")
	var isComboMarket bool = (comboPosition >= 0)
	var base *string = this.SafeCurrencyCode(baseId)
	var quote *string = this.SafeCurrencyCode(quoteId)
	var settle *string = this.SafeCurrencyCode(settleId)
	var typeVar string = "swap"
	if isSpot {
		typeVar = "spot"
	} else if isFuture {
		typeVar = "future"
	} else if isOption {
		typeVar = "option"
	}
	var symbol any = instrumentName
	if !isComboMarket && (base != nil) && (quote != nil) {
		symbol = *base + "/" + *quote
		if !isSpot && (settle != nil) {
			symbol = *base + "/" + *quote + ":" + *settle
		}
	}
	var linear any = func() any {
		if isSpot {
			return nil
		}
		return (settle == quote || (settle != nil && quote != nil && *settle == *quote))
	}()
	var inverse any = func() any {
		if isSpot {
			return nil
		}
		return (settle != quote && (settle == nil || quote == nil || *settle != *quote))
	}()
	var marketSettle *string = func() *string {
		if isSpot {
			return nil
		}
		return settle
	}()
	var marketSettleId *string = func() *string {
		if isSpot {
			return nil
		}
		return settleId
	}()
	var minTradeAmount *float64 = this.SafeNumber(market, "min_trade_amount")
	var tickSize *float64 = this.SafeNumber(market, "tick_size")
	var isFutureOrOption bool = isFuture || isOption
	var expiry *int64 = func() *int64 {
		if isFutureOrOption {
			return this.SafeInteger(market, "expiration_timestamp")
		}
		return nil
	}()
	var active *bool = this.SafeBool(market, "is_active")
	var strike *float64 = this.SafeNumber(market, "strike")
	var optionType *string = this.SafeString(market, "option_type")
	if !isComboMarket && (isOption || isFuture) {
		var expiryString string = this.Yymmdd(expiry, "")
		symbol = Add(Add(symbol, "-"), expiryString)
	}
	if !isComboMarket && isOption {
		var optionTypeLetter string = "P"
		if optionType != nil && *optionType == "call" {
			optionTypeLetter = "C"
		}
		var strikeString *string = this.NumberToString(strike)
		symbol = Add(Add(Add(Add(symbol, "-"), strikeString), "-"), optionTypeLetter)
	}
	var marketStructure map[string]any = map[string]any{
		"id":          instrumentName,
		"lowercaseId": lowercaseId,
		"symbol":      symbol,
		"base":        base,
		"quote":       quote,
		"settle":      marketSettle,
		"baseId":      baseId,
		"quoteId":     quoteId,
		"settleId":    marketSettleId,
		"type":        typeVar,
		"spot":        isSpot,
		"margin":      false,
		"swap":        isPerpetual,
		"future":      isFuture,
		"option":      isOption,
		"active":      active,
		"contract":    !isSpot,
		"linear":      linear,
		"inverse":     inverse,
		"taker":       this.SafeNumber(market, "taker_commission"),
		"maker":       this.SafeNumber(market, "maker_commission"),
		"contractSize": func() any {
			if isSpot {
				return nil
			}
			return this.SafeNumber(market, "contract_size")
		}(),
		"expiry":         expiry,
		"expiryDatetime": this.Iso8601(expiry),
		"strike":         strike,
		"optionType":     optionType,
		"precision": map[string]any{
			"amount": minTradeAmount,
			"price":  tickSize,
		},
		"limits": map[string]any{
			"leverage": map[string]any{
				"min": nil,
				"max": this.SafeNumber(market, "max_leverage"),
			},
			"amount": map[string]any{
				"min": minTradeAmount,
				"max": nil,
			},
			"price": map[string]any{
				"min": nil,
				"max": nil,
			},
			"cost": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"info":    market,
		"created": this.SafeInteger(market, "creation_timestamp"),
	}
	var parsedMarket map[string]any = this.SafeMarketStructure(marketStructure)
	return parsedMarket
}

