func (this *Coinbaseinternational) ParseCurrency(currency any) map[string]any {
	//
	//     {
	//         "decimals": 6,
	//         "currency": "AAVE",
	//         "apr": 0.0,
	//         "min_withdrawal_fee": 0.0,
	//         "withdrawal_fee": 0.0,
	//         "coin_type": "AAVE",
	//         "withdrawal_priorities": [],
	//         "network_fee": 0.0,
	//         "coinbase_networks": [
	//             {
	//                 "display_name": "Ethereum",
	//                 "resource_name": "networks/ethereum-mainnet"
	//             }
	//         ],
	//         "network_currency": "AAVE",
	//         "min_confirmations": 0,
	//         "currency_long": "Aave",
	//         "in_cross_collateral_pool": false,
	//         "onchain_operations_precision": 6,
	//         "currency_uuid": "b1646860-6b23-5f7d-a506-cba0902f0ca9"
	//     }
	//
	var currencyId *string = this.SafeString(currency, "currency")
	var code *string = this.SafeCurrencyCode(currencyId)
	var decimals *string = this.SafeString2(currency, "onchain_operations_precision", "decimals")
	var precision *float64 = this.ParseNumber(this.ParsePrecision(decimals))
	var networkFee *float64 = this.SafeNumber(currency, "network_fee")
	var withdrawalFee *float64 = this.SafeNumber(currency, "withdrawal_fee")
	var rawNetworks []any = SafeListTyped(currency, "coinbase_networks")
	var networks map[string]any = map[string]any{}
	for i := 0; i < len(rawNetworks); i++ {
		var rawNetwork any = rawNetworks[i]
		var networkId *string = this.SafeString(rawNetwork, "resource_name")
		var network *string = this.NetworkIdToCode(networkId, code)
		if network != nil {
			AddElementToObject(networks, network, this.SafeNetwork(map[string]any{
				"info":      rawNetwork,
				"id":        networkId,
				"name":      this.SafeString(rawNetwork, "display_name"),
				"network":   network,
				"active":    nil,
				"deposit":   nil,
				"withdraw":  nil,
				"precision": precision,
				"fee":       networkFee,
				"limits": map[string]any{
					"withdraw": map[string]any{
						"min": nil,
						"max": nil,
					},
					"deposit": map[string]any{
						"min": nil,
						"max": nil,
					},
				},
			}))
		}
	}
	return this.SafeCurrencyStructure(map[string]any{
		"id":        currencyId,
		"name":      this.SafeString(currency, "currency_long"),
		"code":      code,
		"precision": precision,
		"info":      currency,
		"active":    nil,
		"deposit":   nil,
		"withdraw":  nil,
		"networks":  networks,
		"fee":       withdrawalFee,
		"fees": map[string]any{
			"withdraw": withdrawalFee,
		},
		"limits": map[string]any{
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
	})
}

/**
 * @method
 * @name coinbaseinternational#fetchOHLCV
 * @description fetches historical candlestick data containing the open, high, low, and close price, and the volume of a market
 * @see https://docs.cdp.coinbase.com/api-reference/market-data/public-get_tradingview_chart_data
 * @see https://docs.deribit.com/api-reference/market-data/public-get_tradingview_chart_data
 * @param {string} symbol unified symbol of the market to fetch OHLCV data for
 * @param {string} timeframe the length of time each candle represents
 * @param {int} [since] timestamp in ms of the earliest candle to fetch
 * @param {int} [limit] the maximum amount of candles to fetch, default 100 max 10000
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.route] auto (default), deribit, or coinbase; overrides options.route
 * @param {int} [params.until] timestamp in ms of the latest candle to fetch
 * @param {boolean} [params.paginate] default false, when true will automatically paginate by calling this endpoint multiple times. See in the docs all the [available parameters](https://github.com/ccxt/ccxt/wiki/Manual#pagination-params)
 * @returns {int[][]} A list of candles ordered as timestamp, open, high, low, close, volume
 */
func (this *Coinbaseinternational) FetchOHLCVAsync(symbol string, optionalArgs ...any) <-chan AsyncResult[[]OHLCV] {
	ch := make(chan AsyncResult[[]OHLCV], 1)
	go this.fetchOHLCVBody(ch, symbol, optionalArgs...)
	return ch
}
func (this *Coinbaseinternational) fetchOHLCVBody(ch chan AsyncResult[[]OHLCV], symbol string, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var timeframe string = GetArgString(optionalArgs, 0, "1m")
	_ = timeframe
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit int64 = GetArgInt64(optionalArgs, 2, 100)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var paramsResolved any = this.HandleRouteAndParams("fetchOHLCV", params)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	paginate, paramsPaginate := this.HandleOptionBoolAndParams(paramsResolved, "fetchOHLCV", "paginate", false)
	if paginate {

		r1 := <-this.FetchPaginatedCallDeterministicAsync("fetchOHLCV", symbol, since, limit, timeframe, paramsPaginate, 10000)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var retRes84619 []any = r1.Value
		if retRes84619 == nil {
			ch <- AsyncResult[[]OHLCV]{Value: nil}
		} else {
			ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(retRes84619)}
		}
		return nil
	}
	var market map[string]any = this.Market(symbol)
	var request map[string]any = map[string]any{
		"instrument_name": market["id"],
		"resolution":      this.SafeString(this.Timeframes, timeframe, timeframe),
	}
	var marketInfo map[string]any = SafeMapTyped(market, "info")
	if this.IsNativeDeribitCredentials() && (*this.SafeBool2(marketInfo, "is_cbe_routed", "is_csr", false)) {
		panic(NotSupported(this.Id + " fetchOHLCV() is not supported for Coinbase-routed Deribit spot instruments"))
	}
	var limitResolved any = limit
	var duration int64 = this.ParseToInt(this.ParseTimeframe(timeframe))
	var now int64 = this.Milliseconds()
	if since == nil {
		if limitResolved == nil {
			limitResolved = 100
		}
		request["start_timestamp"] = this.Sum(now, ((this.ParseToInt(limitResolved) * duration) * int64(-1000)))
		request["end_timestamp"] = now
	} else {
		var sinceResolved any = mathMax(*since-1, 0)
		request["start_timestamp"] = sinceResolved
		if limitResolved == nil {
			request["end_timestamp"] = now
		} else {
			request["end_timestamp"] = this.Sum(sinceResolved, (this.ParseToInt(limitResolved)*duration)*1000)
		}
	}
	var until *int64 = this.SafeInteger(paramsPaginate, "until")
	if until != nil {
		request["end_timestamp"] = until
	}
	var paramsOmitted map[string]any = func() map[string]any {
		if until != nil {
			return this.OmitDict(paramsPaginate, "until")
		}
		return paramsPaginate
	}()

	r2 := <-this.PublicGetGetTradingviewChartData(this.Extend(request, paramsOmitted))
	if r2.Err != nil {
		panic(r2.Err)
	}
	var response map[string]any = r2.Value
	//
	//     {
	//         "usOut": 1788853501919338,
	//         "usIn": 1788853501916627,
	//         "usDiff": 2711,
	//         "testnet": false,
	//         "result": {
	//             "volume": [0.0001, 0.0168, 0],
	//             "ticks": [1788853380000, 1788853440000, 1788853500000],
	//             "status": "ok",
	//             "open": [78494.0, 78444.0, 78441.0],
	//             "low": [ 78494.0, 78441.0, 78441.0],
	//             "high": [78494.0, 78444.0, 78441.0],
	//             "cost": [7.8494, 1317.8151, 0],
	//             "close": [78494.0, 78441.0, 78441.0]
	//         },
	//         "jsonrpc": "2.0"
	//     }
	//
	var result map[string]any = this.SafeDictMap(response, "result", map[string]any{})
	var candles any = this.ConvertTradingViewToOHLCV(result, "ticks", "open", "high", "low", "close", "volume", true)

	ch <- AsyncResult[[]OHLCV]{Value: OHLCVsFromList(this.ParseOHLCVs(candles, market, timeframe, since, limit))}
	return nil
}
func (this *Coinbaseinternational) ParseOHLCV(ohlcv any, optionalArgs ...any) OHLCV {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var isArray bool = IsArray(ohlcv)
	if isArray {
		return OHLCVFromList(ohlcv)
	}
	return OHLCVFromList([]any{this.Parse8601(this.SafeString2(ohlcv, "start", "time")), this.SafeNumber(ohlcv, "open"), this.SafeNumber(ohlcv, "high"), this.SafeNumber(ohlcv, "low"), this.SafeNumber(ohlcv, "close"), this.SafeNumber(ohlcv, "volume")})
}

/**
 * @method
 * @name coinbaseinternational#fetchFundingRateHistory
 * @description fetches historical funding rate prices
 * @see https://docs.cdp.coinbase.com/api-reference/market-data/public-get_funding_rate_history
 * @see https://docs.deribit.com/api-reference/market-data/public-get_funding_rate_history
 * @param {string} symbol unified symbol of the market to fetch the funding rate history for
 * @param {int} [since] timestamp in ms of the earliest funding rate to fetch
 * @param {int} [limit] the maximum amount of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure} to fetch
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.route] auto (default), deribit, or coinbase; overrides options.route
 * @param {int} [params.until] timestamp in ms of the latest funding rate
 * @param {boolean} [params.paginate] native Deribit automatic pagination is not supported
 * @returns {object[]} a list of [funding rate structures]{@link https://docs.ccxt.com/?id=funding-rate-history-structure}
 */
func (this *Coinbaseinternational) FetchFundingRateHistoryAsync(optionalArgs ...any) <-chan AsyncResult[[]FundingRateHistory] {
	ch := make(chan AsyncResult[[]FundingRateHistory], 1)
	go this.fetchFundingRateHistoryBody(ch, optionalArgs...)
	return ch
}
func (this *Coinbaseinternational) fetchFundingRateHistoryBody(ch chan AsyncResult[[]FundingRateHistory], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbol *string = GetArgStringPtr(optionalArgs, 0, nil)
	_ = symbol
	var since *int64 = GetArgInt64Ptr(optionalArgs, 1, nil)
	_ = since
	var limit *int64 = GetArgInt64Ptr(optionalArgs, 2, nil)
	_ = limit
	var params map[string]any = GetArgMap(optionalArgs, 3, map[string]any{})
	_ = params
	var paramsResolved any = this.HandleRouteAndParams("fetchFundingRateHistory", params)
	var paramsPaginate any = paramsResolved
	if this.IsNativeDeribitCredentials() {
		paginate, paramsFinal := this.HandleOptionBoolAndParams(paramsResolved, "fetchFundingRateHistory", "paginate", false)
		if paginate {
			panic(NotSupported(this.Id + " fetchFundingRateHistory() automatic pagination is not implemented; use since and params.until"))
		}
		paramsPaginate = paramsFinal
	}
	if symbol == nil {
		panic(ArgumentsRequired(this.Id + " fetchFundingRateHistory() requires a symbol argument"))
	}
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var market map[string]any = this.Market(symbol)
	var duration int64 = this.ParseTimeframe("1h") * 1000
	var now int64 = this.Milliseconds()
	var sinceResolved any = since
	if since == nil {
		sinceResolved = now - ((30 * 24) * 60 * 60 * 1000)
	}
	var request map[string]any = map[string]any{
		"instrument_name": market["id"],
		"start_timestamp": sinceResolved,
		"end_timestamp":   now,
	}
	if limit != nil {
		var endTimestamp any = this.Sum(sinceResolved, *limit*duration)
		request["end_timestamp"] = endTimestamp
	}
	var until *int64 = this.SafeInteger(paramsPaginate, "until")
	if until != nil {
		request["end_timestamp"] = until
	}
	var paramsOmitted any = paramsPaginate
	if (until != nil) || this.IsNativeDeribitCredentials() {
		paramsOmitted = this.Omit(paramsPaginate, "until")
	}

	r1 := <-this.PublicGetGetFundingRateHistory(this.Extend(request, paramsOmitted))
	if r1.Err != nil {
		panic(r1.Err)
	}
	var response map[string]any = r1.Value
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "result": [
	//             {
	//                 "timestamp": 1786269600000,
	//                 "index_price": 64832.34,
	//                 "interest_8h": 0.0,
	//                 "interest_1h": 0.0,
	//                 "prev_index_price": 64773.05
	//             },
	//         ],
	//         "usIn": 1788858185989192,
	//         "usOut": 1788858185991663,
	//         "usDiff": 2471,
	//         "testnet": false
	//     }
	//
	var rawRates []any = SafeListTypedDefault(response, "result", []any{})

	ch <- AsyncResult[[]FundingRateHistory]{Value: FundingRateHistoriesFromList(this.ParseFundingRateHistories(rawRates, market, since, limit))}
	return nil
}
func (this *Coinbaseinternational) ParseFundingRateHistory(info any, optionalArgs ...any) any {
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var fundingRate map[string]any = FundingRateToMap(this.ParseFundingRate(info, market))
	return map[string]any{
		"info":        info,
		"symbol":      fundingRate["symbol"],
		"fundingRate": fundingRate["fundingRate"],
		"timestamp":   fundingRate["timestamp"],
		"datetime":    fundingRate["datetime"],
	}
}
func (this *Coinbaseinternational) ParseFundingRate(contract any, optionalArgs ...any) FundingRate {
	//
	// fetchFundingRateHistory
	//
	//     {
	//         "timestamp": 1786269600000,
	//         "index_price": 64832.34,
	//         "interest_8h": 0.0,
	//         "interest_1h": 0.0,
	//         "prev_index_price": 64773.05
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(contract, "timestamp")
	return FundingRateFromMap(map[string]any{
		"info":                     contract,
		"symbol":                   this.SafeSymbol(nil, market),
		"markPrice":                nil,
		"indexPrice":               this.SafeNumber(contract, "index_price"),
		"interestRate":             nil,
		"estimatedSettlePrice":     nil,
		"timestamp":                timestamp,
		"datetime":                 this.Iso8601(timestamp),
		"fundingRate":              this.SafeNumber(contract, "interest_8h"),
		"fundingTimestamp":         timestamp,
		"fundingDatetime":          this.Iso8601(timestamp),
		"nextFundingRate":          nil,
		"nextFundingTimestamp":     nil,
		"nextFundingDatetime":      nil,
		"previousFundingRate":      nil,
		"previousFundingTimestamp": nil,
		"previousFundingDatetime":  nil,
	})
}

/**
 * @method
 * @name coinbaseinternational#fetchTickers
 * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
 * @see https://docs.cdp.coinbase.com/api-reference/market-data/public-ticker
 * @see https://docs.deribit.com/api-reference/market-data/public-ticker
 * @param {string[]|undefined} symbols unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @param {string} [params.route] auto (default), deribit, or coinbase; overrides options.route
 * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
 */
func (this *Coinbaseinternational) FetchTickersAsync(optionalArgs ...any) <-chan AsyncResult[map[string]Ticker] {
	ch := make(chan AsyncResult[map[string]Ticker], 1)
	go this.fetchTickersBody(ch, optionalArgs...)
	return ch
}
func (this *Coinbaseinternational) fetchTickersBody(ch chan AsyncResult[map[string]Ticker], optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var symbols []string = GetArgStringSlice(optionalArgs, 0, nil)
	_ = symbols
	var params map[string]any = GetArgMap(optionalArgs, 1, map[string]any{})
	_ = params
	var paramsResolved any = this.HandleRouteAndParams("fetchTickers", params)
	if this.Markets() == nil {

		r := <-this.LoadMarketsAsync()
		if r.Err != nil {
			panic(r.Err)
		}
	}
	var symbolsResolved []string = this.MarketSymbols(symbols)
	if symbolsResolved == nil {
		panic(ArgumentsRequired(this.Id + " fetchTickers() requires a symbols argument"))
	}
	var tickers map[string]any = map[string]any{}
	for i := 0; i < len(symbolsResolved); i++ {
		var symbol *string = this.SafeString(symbolsResolved, i)
		if symbol == nil {
			continue
		}

		r1 := <-this.FetchTickerAsync(*symbol, paramsResolved)
		if r1.Err != nil {
			panic(r1.Err)
		}
		var ticker any = nil
		if !StructAbsent(r1.Value) {
			ticker = StructBox(r1.Value, TickerToMap)
		}
		AddElementToObject(tickers, symbol, ticker)
	}

	ch <- AsyncResult[map[string]Ticker]{Value: TickerMapFromMap(this.FilterByArrayTickers(tickers, "symbol", symbolsResolved))}
	return nil
}

