	//                 [78421.0, 0.0405],
	//                 [78431.0, 0.0008],
	//                 [78432.0, 0.0001],
	//                 [78433.0, 0.009]
	//             ],
	//             "last_price": 78436.0,
	//             "min_price": 76808.0,
	//             "max_price": 79944.0,
	//             "mark_price": 78375.89,
	//             "best_ask_price": 78419.0,
	//             "best_bid_price": 78376.0,
	//             "best_ask_amount": 0.0015,
	//             "best_bid_amount": 0.0037
	//         },
	//         "usIn": 1788868358451540,
	//         "usOut": 1788868358451883,
	//         "usDiff": 343,
	//         "testnet": false
	//     }
	//
	var result map[string]any = this.SafeDictMap(response, "result", map[string]any{})
	var timestamp *int64 = this.SafeInteger(result, "timestamp")

	ch <- AsyncResult[OrderBook]{Value: OrderBookFromMap(this.ParseOrderBook(result, market["symbol"], timestamp))}
	return nil
